"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96823"],{76061(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.tipo_processo_nao_encontrado_ou_inativo","status":422,"titulo":"Tipo de processo seletivo n\xe3o encontrado ou n\xe3o est\xe1 ativo"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.tipo_processo_nao_encontrado_ou_inativo","requisitos":["UNI-REQ-0018","UNI-REQ-0098"],"oQueAconteceu":["A regra legal informa o c\xf3digo do tipo de processo seletivo a que se aplica, e esse c\xf3digo n\xe3o\\ncorresponde a nenhum tipo cadastrado e ativo no m\xf3dulo Configura\xe7\xe3o. A mensagem da resposta n\xe3o repete o c\xf3digo informado. Nada \xe9 gravado.","O \xfanico c\xf3digo aceito sem cadastro \xe9 `TODOS_OS_TIPOS`, que torna a regra universal, aplic\xe1vel a qualquer tipo de\\nprocesso. Qualquer outro valor precisa ser o c\xf3digo de um tipo ativo: a compara\xe7\xe3o \xe9 exata, com\\ndiferen\xe7a entre mai\xfasculas e min\xfasculas, e espa\xe7os nas pontas s\xe3o recusados.","Tipo desativado tamb\xe9m \xe9 recusado. Na atualiza\xe7\xe3o, a confer\xeancia vale mesmo quando o tipo da regra\\nn\xe3o mudou: uma regra que cita um tipo desativado depois do cadastro n\xe3o pode ser alterada enquanto\\no tipo continuar inativo.","A confer\xeancia do tipo vem depois da permiss\xe3o para manter obrigatoriedades legais, da leitura do\\ncorpo da requisi\xe7\xe3o, da confer\xeancia dos campos pelas regras do dom\xednio (cujas recusas t\xeam status 422\\ne c\xf3digo pr\xf3prio por campo, como\\n[`tipo_processo_codigo_obrigatorio`](/erros/uniplus.selecao.obrigatoriedade_legal.tipo_processo_codigo_obrigatorio)\\ne\\n[`tipo_processo_codigo_invalido`](/erros/uniplus.selecao.obrigatoriedade_legal.tipo_processo_codigo_invalido))\\ne, na atualiza\xe7\xe3o, de a regra ser encontrada\\n([`nao_encontrada`](/erros/uniplus.selecao.obrigatoriedade_legal.nao_encontrada)). Vem antes da\\nconfer\xeancia dos c\xf3digos que o predicado cita (por exemplo,\\n[`tipo_etapa_nao_encontrado_ou_inativo`](/erros/uniplus.selecao.obrigatoriedade_legal.tipo_etapa_nao_encontrado_ou_inativo))\\ne da de c\xf3digo de regra j\xe1 em uso\\n([`regra_codigo_duplicada`](/erros/uniplus.selecao.obrigatoriedade_legal.regra_codigo_duplicada)).\\nQuando mais de um ponto est\xe1 errado, responde primeiro o que vem antes nessa ordem.","H\xe1 um c\xf3digo parecido no cadastro de processo seletivo,\\n[`processo_seletivo.tipo_processo_nao_encontrado_ou_inativo`](/erros/uniplus.selecao.processo_seletivo.tipo_processo_nao_encontrado_ou_inativo),\\ncom a mesma causa em outra opera\xe7\xe3o; o campo `code` do corpo de erro diz qual dos dois foi emitido."],"comoResolver":["Confira o c\xf3digo do tipo na listagem de tipos de processo do m\xf3dulo Configura\xe7\xe3o e use o de um tipo\\nativo. Para uma regra que vale para todos os tipos, informe `TODOS_OS_TIPOS`. Se o tipo desejado foi desativado,\\nquem mant\xe9m o cadastro de tipos de processo pode reativ\xe1-lo, e o c\xf3digo continua o mesmo."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);